uint32_t r_json_simple_fold(uint32_t scalar) {
    size_t low = 0U;
    size_t high = sizeof(r_json_fold_pairs) / sizeof(r_json_fold_pairs[0]);
    while (low < high) {
        size_t middle = low + (high - low) / 2U;
        if (r_json_fold_pairs[middle].scalar < scalar)
            low = middle + 1U;
        else if (r_json_fold_pairs[middle].scalar > scalar)
            high = middle;
        else
            return r_json_fold_pairs[middle].canonical;
    }
    return scalar;
}
